import json, time
path='agent_comms.json'; my_agent='codex'; interval=10
def ids(p):
    with open(p) as f: return {m['id']:m for m in json.load(f).get('messages',[])}
known=ids(path)
print(f'Polling {path} every {interval}s')
while True:
    time.sleep(interval)
    cur=ids(path)
    for mid,msg in cur.items():
        if mid in known or msg.get('from')==my_agent or msg.get('status')=='resolved': continue
        print(f"\nNEW: {mid} [{msg.get('type')}] from {msg.get('from')}\nSubject: {msg.get('subject')}\n{(msg.get('body') or '')[:300]}")
    known=cur
